GRANT ALL PRIVILEGES ON TABLE tickers TO public;
GRANT ALL PRIVILEGES ON TABLE prices TO public;
GRANT ALL PRIVILEGES ON TABLE news TO public;
GRANT ALL PRIVILEGES ON TABLE filings TO public

select * from (
SELECT sector, COUNT(*) AS company_count FROM tickers GROUP BY sector ORDER BY company_count DESC
) as limited limit 1000

select * from (
SELECT symbol, name FROM tickers WHERE sector = 'Health Care'
) as limited limit 1000

select * from (
SELECT close FROM prices WHERE symbol = 'AAPL' AND date = '2026-11-16'
) as limited limit 1000

select * from (
SELECT MAX(p.close) AS max_close FROM prices p WHERE p.symbol = 'NVDA'
) as limited limit 1000

select * from (
SELECT AVG(volume) AS avg_volume FROM prices WHERE symbol = 'TSLA' AND date BETWEEN '2025-01-01' AND '2025-12-31'
) as limited limit 1000

select * from (
SELECT COUNT(*) FROM prices p WHERE p.symbol = 'MSFT' AND p.date BETWEEN '2024-01-01' AND '2024-12-31'
) as limited limit 1000

select * from (
SELECT COUNT(*) FROM filings WHERE form_type = '8-K' AND filed_at BETWEEN '2025-01-01' AND '2025-12-31'
) as limited limit 1000

select * from (
SELECT MIN(close) AS lowest_close FROM prices WHERE symbol = 'JPM' AND date BETWEEN '2023-01-01' AND '2023-12-31'
) as limited limit 1000

select * from (
SELECT p.close FROM prices p WHERE p.symbol = 'GOOGL' AND p.date = (SELECT date '2026-11-16' - interval '1 year')
) as limited limit 1000

select * from (
WITH latest_date AS (
  SELECT MAX(date) AS latest FROM prices WHERE symbol = 'AAPL'
)
SELECT AVG(close) AS avg_close FROM prices p, latest_date ld WHERE p.symbol = 'AAPL' AND p.date BETWEEN ld.latest - INTERVAL '50 days' AND ld.latest
) as limited limit 1000
